import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
const html=readFileSync(new URL('../index.php',import.meta.url),'utf8');
const showcase=readFileSync(new URL('../studio-next.js',import.meta.url),'utf8');
const script=readFileSync(new URL('../script.js',import.meta.url),'utf8');
const native=readFileSync(new URL('../scripts/build-native-web.mjs',import.meta.url),'utf8');
const sw=readFileSync(new URL('../sw.js',import.meta.url),'utf8');
const manual=script.slice(script.indexOf('window.manualUpdateApplication ='), script.indexOf('let serviceWorkerRegistrationPromise'));
assert.ok(manual.length>400);
assert.match(manual,/checkNativeLiveUpdate\(true, true\)/);
assert.doesNotMatch(manual,/apkInstaller|installer\.check|installer\.install|dag-apk-update-progress/);
assert.match(html,/id="android-apk-download-btn"/);
assert.match(html,/onclick="manualUpdateApplication\(\)"/);
assert.match(html,/setTimeout\(reveal,3500\)/);
assert.doesNotMatch(html,/setTimeout\([^;]+12000/);
assert.match(showcase,/dispatchEvent\(new Event\('dag-ui-ready'\)\)/);
assert.match(html,/fonts\.googleapis\.com[^"]+" rel="stylesheet" media="print" onload=/);
assert.match(html,/font-awesome\/6\.4\.0\/css\/all\.min\.css" media="print" onload=/);
assert.match(manual,/AbortController\(\)/);
assert.match(manual,/7500/);
assert.match(manual,/serviceWorkerRegistrationPromise/);
assert.match(sw,/dagstudio-player-shell-v2324/);
assert.match(html,/script\.js\?v=2316/);
assert.match(html,/studio-next\.js\?v=14/);
assert.match(native,/native-bridge\.js/);
assert.match(native,/studio-next\.js/);
console.log('FAST_BOOT_OTA_ONLY_PWA_NONBLOCKING_FONTS_OK');
